Here is the root cause:
The function `ocelot_port_xmit_inj()` in the file `ocelot_net.c` calls `ocelot_can_inject()` and `ocelot_port_inject_frame()` without first acquiring the injection group lock (via `ocelot_lock_inj_grp()`). These functions require the lock to be held (they contain `lockdep_assert_held()` for the injection lock), and the correct caller `felix_port_deferred_xmit()` properly acquires it. The missing lock protection leads to potential race conditions when multiple callers access the injection registers concurrently, causing data corruption or lockdep warnings.

Here is the patch:

 static netdev_tx_t ocelot_port_xmit_inj(struct sk_buff *skb,
 					struct net_device *dev)
 {
 	struct ocelot_port_private *priv = netdev_priv(dev);
 	struct ocelot_port *ocelot_port = &priv->port;
 	struct ocelot *ocelot = ocelot_port->ocelot;
 	int port = priv->port.index;
 	u32 rew_op = 0;

-	if (!ocelot_can_inject(ocelot, 0))
+	ocelot_lock_inj_grp(ocelot, 0);
+
+	if (!ocelot_can_inject(ocelot, 0)) {
+		ocelot_unlock_inj_grp(ocelot, 0);
 		return NETDEV_TX_BUSY;
+	}

-	if (!ocelot_xmit_timestamp(ocelot, port, skb, &rew_op))
+	if (!ocelot_xmit_timestamp(ocelot, port, skb, &rew_op)) {
+		ocelot_unlock_inj_grp(ocelot, 0);
 		return NETDEV_TX_OK;
+	}

 	ocelot_port_inject_frame(ocelot, port, 0, rew_op, skb);

+	ocelot_unlock_inj_grp(ocelot, 0);
+
 	consume_skb(skb);

 	return NETDEV_TX_OK;
 }



